import { defineConfig, devices } from "@playwright/test";

/**
 * Playwright harness. The two happy-path E2E suites are built in M9; this
 * config boots the dev server (which needs a running local Supabase and a
 * populated .env.local) and runs specs from tests/e2e.
 */
export default defineConfig({
  testDir: "./tests/e2e",
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  reporter: "list",
  use: {
    baseURL: "http://127.0.0.1:3000",
    trace: "on-first-retry",
  },
  projects: [
    { name: "chromium", use: { ...devices["Desktop Chrome"] } },
  ],
  webServer: {
    command: "npm run dev",
    url: "http://127.0.0.1:3000",
    reuseExistingServer: !process.env.CI,
    timeout: 120_000,
  },
});

import "@testing-library/jest-dom/vitest";
import { afterEach, expect } from "vitest";
import { cleanup } from "@testing-library/react";
import { toHaveNoViolations } from "jest-axe";

expect.extend(toHaveNoViolations);

afterEach(() => {
  cleanup();
});

import { describe, it, expect, afterEach } from "vitest";
import {
  priceForBlock,
  overageMinutes,
  computeSessionAccounting,
  addTip,
  cancellationOutcome,
  getCommissionRate,
  roundHalfUp,
} from "@/lib/pricing";

const PROVIDER = {
  price_block_15_cents: 1200,
  price_block_30_cents: 2400,
  price_block_45_cents: 3600,
};

describe("priceForBlock", () => {
  it("returns the cents for each block length", () => {
    expect(priceForBlock(PROVIDER, 15)).toBe(1200);
    expect(priceForBlock(PROVIDER, 30)).toBe(2400);
    expect(priceForBlock(PROVIDER, 45)).toBe(3600);
  });
});

describe("roundHalfUp", () => {
  it("rounds halves up", () => {
    expect(roundHalfUp(120)).toBe(120);
    expect(roundHalfUp(120.5)).toBe(121);
    expect(roundHalfUp(120.49)).toBe(120);
    expect(roundHalfUp(121.5)).toBe(122);
  });
});

describe("overageMinutes", () => {
  it("is zero within the block", () => {
    expect(overageMinutes(1800, 30)).toBe(0);
    expect(overageMinutes(1799, 30)).toBe(0);
    expect(overageMinutes(0, 15)).toBe(0);
  });
  it("rounds part-minutes up past the block", () => {
    expect(overageMinutes(1801, 30)).toBe(1);
    expect(overageMinutes(1860, 30)).toBe(1);
    expect(overageMinutes(1861, 30)).toBe(2);
    expect(overageMinutes(2700, 30)).toBe(15); // ran a full extra 15 min
  });
});

describe("computeSessionAccounting", () => {
  it("charges just the block when there is no overage (5% commission)", () => {
    const r = computeSessionAccounting({
      priceBlockCents: 2400,
      overagePerMinCents: 80,
      elapsedSeconds: 1500,
      blockMinutes: 30,
      commissionRate: 0.05,
    });
    expect(r).toEqual({
      overageMinutes: 0,
      totalCents: 2400,
      commissionCents: 120,
      providerEarningsCents: 2280,
    });
  });

  it("adds overage minutes × the per-minute rate", () => {
    const r = computeSessionAccounting({
      priceBlockCents: 2400,
      overagePerMinCents: 80,
      elapsedSeconds: 1800 + 5 * 60 + 1, // 5m1s over → 6 overage minutes
      blockMinutes: 30,
      commissionRate: 0.05,
    });
    expect(r.overageMinutes).toBe(6);
    expect(r.totalCents).toBe(2400 + 6 * 80); // 2880
    expect(r.commissionCents).toBe(144); // 2880 * 0.05
    expect(r.providerEarningsCents).toBe(2880 - 144);
  });

  it("rounds commission half-up", () => {
    // 2410 * 0.05 = 120.5 → 121
    const r = computeSessionAccounting({
      priceBlockCents: 2410,
      overagePerMinCents: 0,
      elapsedSeconds: 60,
      blockMinutes: 30,
      commissionRate: 0.05,
    });
    expect(r.commissionCents).toBe(121);
    expect(r.providerEarningsCents).toBe(2289);
  });

  it("total + commission split is always exact (no lost cents)", () => {
    const r = computeSessionAccounting({
      priceBlockCents: 3333,
      overagePerMinCents: 77,
      elapsedSeconds: 3000,
      blockMinutes: 30,
      commissionRate: 0.05,
    });
    expect(r.commissionCents + r.providerEarningsCents).toBe(r.totalCents);
  });
});

describe("addTip", () => {
  it("adds the tip to earnings with no commission taken", () => {
    expect(addTip(2280, 500)).toBe(2780);
  });
  it("ignores negative tips", () => {
    expect(addTip(2280, -100)).toBe(2280);
  });
});

describe("cancellationOutcome", () => {
  const now = Date.parse("2026-06-10T12:00:00.000Z");

  it("fully releases when cancelled ≥1h before a scheduled session", () => {
    const r = cancellationOutcome({
      priceBlockCents: 2400,
      scheduledAt: "2026-06-10T14:00:00.000Z",
      nowMs: now,
    });
    expect(r).toEqual({ action: "release", captureCents: 0 });
  });

  it("charges the full block when cancelled <1h before", () => {
    const r = cancellationOutcome({
      priceBlockCents: 2400,
      scheduledAt: "2026-06-10T12:30:00.000Z",
      nowMs: now,
    });
    expect(r).toEqual({ action: "charge", captureCents: 2400 });
  });

  it("charges the full block for a now booking (no scheduled time)", () => {
    const r = cancellationOutcome({
      priceBlockCents: 1200,
      scheduledAt: null,
      nowMs: now,
    });
    expect(r).toEqual({ action: "charge", captureCents: 1200 });
  });
});

describe("getCommissionRate", () => {
  const original = process.env.PLATFORM_COMMISSION_RATE;
  afterEach(() => {
    process.env.PLATFORM_COMMISSION_RATE = original;
  });

  it("reads the configured rate", () => {
    process.env.PLATFORM_COMMISSION_RATE = "0.1";
    expect(getCommissionRate()).toBe(0.1);
  });

  it("falls back to 0.05 for missing/invalid values", () => {
    delete process.env.PLATFORM_COMMISSION_RATE;
    expect(getCommissionRate()).toBe(0.05);
    process.env.PLATFORM_COMMISSION_RATE = "nonsense";
    expect(getCommissionRate()).toBe(0.05);
    process.env.PLATFORM_COMMISSION_RATE = "2";
    expect(getCommissionRate()).toBe(0.05);
  });
});

/**
 * The single source of truth for all pricing & accounting (CLAUDE.md rule 3).
 * Pure functions only — no DB, no side effects. Money is ALWAYS integer cents;
 * never use floats to represent money. The commission rate comes from config
 * (PLATFORM_COMMISSION_RATE), never a literal.
 *
 * No pricing math may live anywhere else in the codebase.
 */

export type BlockMinutes = 15 | 30 | 45;

/** Minimal provider shape needed to price a block. */
export interface BlockPricing {
  price_block_15_cents: number;
  price_block_30_cents: number;
  price_block_45_cents: number;
}

const DEFAULT_COMMISSION_RATE = 0.05;

/** Platform commission rate from config, clamped to [0, 1]; 0.05 fallback. */
export function getCommissionRate(): number {
  const raw = Number(process.env.PLATFORM_COMMISSION_RATE ?? DEFAULT_COMMISSION_RATE);
  if (!Number.isFinite(raw) || raw < 0 || raw > 1) return DEFAULT_COMMISSION_RATE;
  return raw;
}

/** Round to the nearest cent, half-up. Inputs are non-negative money amounts. */
export function roundHalfUp(value: number): number {
  return Math.floor(value + 0.5);
}

/** The block price (cents) a customer authorises at booking time. */
export function priceForBlock(
  provider: BlockPricing,
  blockMinutes: BlockMinutes,
): number {
  switch (blockMinutes) {
    case 15:
      return provider.price_block_15_cents;
    case 30:
      return provider.price_block_30_cents;
    case 45:
      return provider.price_block_45_cents;
  }
}

/** Whole minutes run past the block (rounded up); 0 within the block. */
export function overageMinutes(
  elapsedSeconds: number,
  blockMinutes: BlockMinutes,
): number {
  const overSeconds = elapsedSeconds - blockMinutes * 60;
  if (overSeconds <= 0) return 0;
  return Math.ceil(overSeconds / 60);
}

export interface SessionAccountingInput {
  priceBlockCents: number;
  overagePerMinCents: number;
  elapsedSeconds: number;
  blockMinutes: BlockMinutes;
  /** Defaults to the configured platform rate. */
  commissionRate?: number;
}

export interface SessionAccounting {
  overageMinutes: number;
  totalCents: number;
  commissionCents: number;
  providerEarningsCents: number;
}

/**
 * Final accounting at session end: block + overage → total, commission (half-up)
 * from config, provider keeps the rest. Tips are added later (addTip) and are
 * NOT subject to commission.
 */
export function computeSessionAccounting({
  priceBlockCents,
  overagePerMinCents,
  elapsedSeconds,
  blockMinutes,
  commissionRate = getCommissionRate(),
}: SessionAccountingInput): SessionAccounting {
  const overage = overageMinutes(elapsedSeconds, blockMinutes);
  const totalCents = priceBlockCents + overage * overagePerMinCents;
  const commissionCents = roundHalfUp(totalCents * commissionRate);
  const providerEarningsCents = totalCents - commissionCents;
  return {
    overageMinutes: overage,
    totalCents,
    commissionCents,
    providerEarningsCents,
  };
}

/** Add a tip to provider earnings. Tips carry no platform commission. */
export function addTip(providerEarningsCents: number, tipCents: number): number {
  return providerEarningsCents + Math.max(0, tipCents);
}

export interface CancellationInput {
  priceBlockCents: number;
  /** ISO time of a scheduled session, if any. */
  scheduledAt?: string | null;
  /** "Now" in epoch ms (injected for testability). */
  nowMs: number;
}

export interface CancellationOutcome {
  /** "release" fully releases the hold; "charge" captures the full block. */
  action: "release" | "charge";
  captureCents: number;
}

const ONE_HOUR_MS = 60 * 60 * 1000;

/**
 * Cancellation policy (SPEC §5): cancelling a scheduled session ≥1h before its
 * start fully releases the hold; otherwise the full block is charged. (Ending an
 * in-progress call early still charges the full block — handled naturally by
 * computeSessionAccounting, since elapsed < block yields zero overage.)
 */
export function cancellationOutcome({
  priceBlockCents,
  scheduledAt,
  nowMs,
}: CancellationInput): CancellationOutcome {
  if (scheduledAt) {
    const startMs = new Date(scheduledAt).getTime();
    if (Number.isFinite(startMs) && startMs - nowMs >= ONE_HOUR_MS) {
      return { action: "release", captureCents: 0 };
    }
  }
  return { action: "charge", captureCents: priceBlockCents };
}

import { describe, it, expect } from "vitest";
import { summarizeEarnings } from "@/lib/earnings";

const NOW = Date.parse("2026-06-15T12:00:00.000Z");
const iso = (s: string) => s;

describe("summarizeEarnings", () => {
  it("sums lifetime, this-month, this-week earnings + tips", () => {
    const r = summarizeEarnings({
      sessions: [
        { provider_earnings_cents: 2280, ended_at: iso("2026-06-14T10:00:00Z") }, // this week
        { provider_earnings_cents: 1900, ended_at: iso("2026-06-03T10:00:00Z") }, // this month, not week
        { provider_earnings_cents: 1000, ended_at: iso("2026-05-20T10:00:00Z") }, // older
      ],
      tips: [
        { tip_cents: 500, created_at: iso("2026-06-14T11:00:00Z") }, // this week
        { tip_cents: 200, created_at: iso("2026-05-01T11:00:00Z") }, // older
      ],
      payouts: [],
      nowMs: NOW,
    });
    expect(r.lifetimeCents).toBe(2280 + 1900 + 1000 + 500 + 200); // 5880
    expect(r.thisMonthCents).toBe(2280 + 1900 + 500); // 4680
    expect(r.thisWeekCents).toBe(2280 + 500); // 2780
    expect(r.sessionsThisWeek).toBe(1);
  });

  it("computes paid-out, pending balance, and the next payout date", () => {
    const r = summarizeEarnings({
      sessions: [
        { provider_earnings_cents: 3000, ended_at: iso("2026-06-10T10:00:00Z") },
      ],
      tips: [],
      payouts: [
        { amount_cents: 1000, status: "paid", scheduled_for: "2026-06-07T00:00:00Z" },
        { amount_cents: 2000, status: "scheduled", scheduled_for: "2026-06-20T00:00:00Z" },
        { amount_cents: 999, status: "scheduled", scheduled_for: "2026-06-18T00:00:00Z" },
      ],
      nowMs: NOW,
    });
    expect(r.paidOutCents).toBe(1000);
    expect(r.pendingCents).toBe(3000 - 1000); // 2000
    expect(r.nextPayoutAt).toBe("2026-06-18T00:00:00Z"); // soonest future scheduled
  });

  it("has no next payout when none are scheduled in the future", () => {
    const r = summarizeEarnings({
      sessions: [],
      tips: [],
      payouts: [
        { amount_cents: 500, status: "scheduled", scheduled_for: "2026-06-01T00:00:00Z" },
      ],
      nowMs: NOW,
    });
    expect(r.nextPayoutAt).toBeNull();
    expect(r.pendingCents).toBe(0);
  });
});

import { describe, it, expect } from "vitest";
import { type SupabaseClient } from "@supabase/supabase-js";
import { type Database } from "@/lib/supabase/types";
import {
  createMockPayments,
  aggregateEarnings,
  customerIdFromRef,
  mockRef,
} from "@/lib/integrations/payments/mock";
import { createMockCalls } from "@/lib/integrations/calls/mock";
import { createMockBackgroundCheck } from "@/lib/integrations/background-check/mock";
import { createRealPayments } from "@/lib/integrations/payments/real";
import { createRealCalls } from "@/lib/integrations/calls/real";
import { createRealBackgroundCheck } from "@/lib/integrations/background-check/real";

/**
 * Minimal fake of the Supabase query-builder surface the payments mock uses:
 * .from(table).insert(row) | .update(patch).eq() | .select().eq().gte().lte().gt()
 * Records insert/update operations and returns canned select data.
 */
interface Op {
  table: string;
  op: "insert" | "update";
  payload: unknown;
}
function makeFakeDb(canned: Record<string, unknown[]> = {}) {
  const ops: Op[] = [];
  function from(table: string) {
    let op: "insert" | "update" | "select" = "select";
    let payload: unknown = null;
    const chain = {
      insert(row: unknown) {
        op = "insert";
        payload = row;
        ops.push({ table, op, payload });
        return chain;
      },
      update(patch: unknown) {
        op = "update";
        payload = patch;
        return chain;
      },
      select() {
        return chain;
      },
      eq() {
        if (op === "update") ops.push({ table, op, payload });
        return chain;
      },
      gte() {
        return chain;
      },
      lte() {
        return chain;
      },
      gt() {
        return chain;
      },
      then(resolve: (v: { data: unknown[] | null; error: null }) => void) {
        resolve({ data: op === "select" ? (canned[table] ?? []) : null, error: null });
      },
    };
    return chain;
  }
  return { db: { from } as unknown as SupabaseClient<Database>, ops };
}

describe("mock payments refs", () => {
  it("builds and decodes the customer ref", () => {
    expect(mockRef.customer("u1")).toBe("mock_cus_u1");
    expect(customerIdFromRef("mock_cus_u1")).toBe("u1");
    expect(customerIdFromRef("raw-id")).toBe("raw-id");
  });
});

describe("createMockPayments", () => {
  it("ensureCustomer / ensureConnectedAccount return synthetic refs", async () => {
    const { db } = makeFakeDb();
    const pay = createMockPayments(db);
    expect((await pay.ensureCustomer("u1")).customerRef).toBe("mock_cus_u1");
    expect((await pay.ensureConnectedAccount("p1")).accountRef).toBe(
      "mock_acct_p1",
    );
  });

  it("authorizeHold writes an authorized ledger row with a mock_pay_ ref", async () => {
    const { db, ops } = makeFakeDb();
    const pay = createMockPayments(db);
    const res = await pay.authorizeHold({
      bookingId: "b1",
      amountCents: 2400,
      customerRef: "mock_cus_c1",
    });
    expect(res.status).toBe("authorized");
    expect(res.paymentRef).toMatch(/^mock_pay_/);
    expect(ops).toHaveLength(1);
    expect(ops[0]).toMatchObject({ table: "payments", op: "insert" });
    expect(ops[0].payload).toMatchObject({
      booking_id: "b1",
      customer_id: "c1",
      amount_cents: 2400,
      status: "authorized",
      payment_ref: res.paymentRef,
    });
  });

  it("capture marks the ledger row captured with the final amount", async () => {
    const { db, ops } = makeFakeDb();
    const pay = createMockPayments(db);
    const res = await pay.capture({ paymentRef: "mock_pay_x", amountCents: 2880 });
    expect(res).toEqual({ status: "captured" });
    expect(ops[0]).toMatchObject({
      table: "payments",
      op: "update",
      payload: { status: "captured", amount_cents: 2880 },
    });
  });

  it("refund marks the ledger row refunded", async () => {
    const { db, ops } = makeFakeDb();
    const pay = createMockPayments(db);
    const res = await pay.refund({ paymentRef: "mock_pay_x", amountCents: 2400 });
    expect(res).toEqual({ status: "refunded" });
    expect(ops[0]).toMatchObject({ payload: { status: "refunded" } });
  });

  it("recordProviderEarning is a no-op that resolves", async () => {
    const { db } = makeFakeDb();
    const pay = createMockPayments(db);
    await expect(
      pay.recordProviderEarning({
        providerId: "p1",
        amountCents: 100,
        sessionId: "s1",
      }),
    ).resolves.toBeUndefined();
  });

  it("runWeeklyPayouts aggregates earnings + tips into payout rows", async () => {
    const { db, ops } = makeFakeDb({
      sessions: [
        { provider_id: "p1", provider_earnings_cents: 2000 },
        { provider_id: "p1", provider_earnings_cents: 1000 },
        { provider_id: "p2", provider_earnings_cents: 500 },
      ],
      reviews: [{ provider_id: "p1", tip_cents: 300 }],
    });
    const pay = createMockPayments(db);
    const { payouts } = await pay.runWeeklyPayouts({
      periodStart: "2026-06-01T00:00:00.000Z",
      periodEnd: "2026-06-08T00:00:00.000Z",
    });
    expect(payouts).toEqual([
      { providerId: "p1", amountCents: 3300 },
      { providerId: "p2", amountCents: 500 },
    ]);
    const insert = ops.find((o) => o.table === "payouts" && o.op === "insert");
    expect(insert).toBeTruthy();
    expect(insert!.payload).toHaveLength(2);
  });
});

describe("aggregateEarnings", () => {
  it("sums per provider, drops zero totals, sorts by id", () => {
    expect(
      aggregateEarnings(
        [
          { provider_id: "b", provider_earnings_cents: 100 },
          { provider_id: "a", provider_earnings_cents: 50 },
          { provider_id: "c", provider_earnings_cents: 0 },
        ],
        [{ provider_id: "a", tip_cents: 25 }],
      ),
    ).toEqual([
      { providerId: "a", amountCents: 75 },
      { providerId: "b", amountCents: 100 },
    ]);
  });
});

describe("createMockCalls", () => {
  it("returns synthetic refs and mock mode", async () => {
    const calls = createMockCalls();
    const { callSessionRef } = await calls.createSession({
      bookingId: "b1",
      providerId: "p1",
      customerId: "c1",
      maxMinutes: 30,
    });
    expect(callSessionRef).toMatch(/^mock_call_/);

    const join = await calls.getJoinInfo({
      callSessionRef,
      role: "participant",
      userId: "c1",
    });
    expect(join.mockMode).toBe(true);
    expect(join.joinRef).toContain(callSessionRef);

    const ended = await calls.endSession({ callSessionRef });
    expect(Number.isNaN(Date.parse(ended.endedAt))).toBe(false);
  });
});

describe("createMockBackgroundCheck", () => {
  it("initiates pending and stays pending until an admin clears it", async () => {
    const bg = createMockBackgroundCheck();
    const init = await bg.initiate({ providerId: "p1" });
    expect(init).toEqual({ checkRef: "mock_chk_p1", status: "pending" });
    expect((await bg.getStatus({ checkRef: init.checkRef })).status).toBe(
      "pending",
    );
  });
});

describe("real adapters (stubs)", () => {
  it("throw a clear TODO error until the real integration is wired", async () => {
    await expect(createRealPayments().authorizeHold({} as never)).rejects.toThrow(
      /Stripe Connect not configured/,
    );
    await expect(createRealCalls().createSession({} as never)).rejects.toThrow(
      /Zoom Meeting SDK not configured/,
    );
    await expect(
      createRealBackgroundCheck().initiate({} as never),
    ).rejects.toThrow(/Checkr not configured/);
  });
});

"use server";

import { redirect } from "next/navigation";
import { revalidatePath } from "next/cache";
import { getUser, requireRole } from "@/lib/auth";
import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { getCalls } from "@/lib/integrations/calls";
import { getPayments } from "@/lib/integrations/payments";
import { computeSessionAccounting, roundHalfUp } from "@/lib/pricing";
import { type BlockMinutes } from "@/lib/pricing";
import { reviewSchema, type ReviewInput } from "@/lib/validation/schemas";
import { t } from "@/lib/i18n";

async function loadBookingForParty(bookingId: string) {
  const user = await getUser();
  if (!user) redirect("/signin");
  const supabase = await createClient();
  const { data: booking } = await supabase
    .from("bookings")
    .select("*")
    .eq("id", bookingId)
    .maybeSingle();
  // RLS already restricts to a party; double-check defensively.
  if (
    !booking ||
    (booking.customer_id !== user.id && booking.provider_id !== user.id)
  ) {
    return null;
  }
  return booking;
}

export interface StartSessionResult {
  sessionId?: string;
  error?: string;
}

/**
 * Start (or re-join) the mock call for a booking. Idempotent: returns the
 * existing session if one already exists. Creates the call session via the
 * calls adapter and the sessions row via the service-role client.
 */
export async function startSession(
  bookingId: string,
): Promise<StartSessionResult> {
  const booking = await loadBookingForParty(bookingId);
  if (!booking) return { error: "This session isn't available." };

  // Block the call if EITHER party is suspended — protects both sides,
  // independent of who initiated. A provider suspended via the approval queue
  // carries providers.status='suspended'; a user suspended by an admin carries
  // profiles.is_suspended. Read both via the service role since RLS hides each
  // party's row from the other.
  const admin = createAdminClient();
  const [{ data: parties }, { data: prov }] = await Promise.all([
    admin
      .from("profiles")
      .select("id, is_suspended")
      .in("id", [booking.customer_id, booking.provider_id]),
    admin
      .from("providers")
      .select("status")
      .eq("id", booking.provider_id)
      .maybeSingle(),
  ]);
  const eitherSuspended =
    (parties ?? []).some((p) => p.is_suspended) || prov?.status === "suspended";
  if (eitherSuspended) return { error: t("booking.suspended") };

  const supabase = await createClient();
  const { data: existing } = await supabase
    .from("sessions")
    .select("id")
    .eq("booking_id", bookingId)
    .maybeSingle();
  if (existing) return { sessionId: existing.id };

  const calls = getCalls();
  const { callSessionRef } = await calls.createSession({
    bookingId,
    providerId: booking.provider_id,
    customerId: booking.customer_id,
    maxMinutes: booking.block_minutes + 15,
  });

  const { data: session, error } = await admin
    .from("sessions")
    .insert({
      booking_id: bookingId,
      provider_id: booking.provider_id,
      customer_id: booking.customer_id,
      call_session_ref: callSessionRef,
      started_at: new Date().toISOString(),
      block_minutes: booking.block_minutes,
      status: "in_progress",
    })
    .select("id")
    .single();
  if (error || !session) return { error: "We couldn't start the call." };

  await supabase
    .from("bookings")
    .update({ status: "in_progress" })
    .eq("id", bookingId);

  return { sessionId: session.id };
}

export interface EndSessionResult {
  ok?: true;
  error?: string;
}

/**
 * End the mock call. The client's count-up timer is the source of truth for
 * elapsed seconds (mock mode). Computes the final accounting (block + overage +
 * commission), captures the hold, and marks the session + booking completed.
 * Idempotent: a session already completed is left as-is.
 */
export async function endSession(
  bookingId: string,
  elapsedSeconds: number,
): Promise<EndSessionResult> {
  const booking = await loadBookingForParty(bookingId);
  if (!booking) return { error: "This session isn't available." };

  const supabase = await createClient();
  const { data: session } = await supabase
    .from("sessions")
    .select("*")
    .eq("booking_id", bookingId)
    .maybeSingle();
  if (!session) return { error: "This session isn't available." };
  if (session.status === "completed") return { ok: true };

  const elapsed = Math.max(0, Math.floor(elapsedSeconds || 0));
  const accounting = computeSessionAccounting({
    priceBlockCents: booking.price_block_cents,
    overagePerMinCents: booking.overage_per_min_cents,
    elapsedSeconds: elapsed,
    blockMinutes: booking.block_minutes as BlockMinutes,
  });

  const calls = getCalls();
  if (session.call_session_ref) {
    await calls.endSession({ callSessionRef: session.call_session_ref });
  }

  const payments = getPayments();
  if (booking.payment_ref) {
    await payments.capture({
      paymentRef: booking.payment_ref,
      amountCents: accounting.totalCents,
    });
  }

  const admin = createAdminClient();
  const { error } = await admin
    .from("sessions")
    .update({
      ended_at: new Date().toISOString(),
      elapsed_seconds: elapsed,
      overage_minutes: accounting.overageMinutes,
      total_price_cents: accounting.totalCents,
      commission_cents: accounting.commissionCents,
      provider_earnings_cents: accounting.providerEarningsCents,
      status: "completed",
    })
    .eq("id", session.id);
  if (error) return { error: "We couldn't finish the call." };

  await supabase
    .from("bookings")
    .update({ status: "completed" })
    .eq("id", bookingId);

  return { ok: true };
}

export interface ReviewResult {
  ok?: true;
  error?: string;
}

/**
 * Submit a post-session review + optional tip. Inserts the review (RLS:
 * customer owns it), recomputes the provider's rating, and revalidates. Tips
 * carry no commission and are aggregated into payouts from the reviews table
 * (so they're not double-counted on the session row).
 */
export async function submitReview(input: ReviewInput): Promise<ReviewResult> {
  const profile = await requireRole("customer");
  const parsed = reviewSchema.safeParse(input);
  if (!parsed.success) return { error: "Please choose a rating." };
  const d = parsed.data;

  const supabase = await createClient();

  // The session must be the caller's own, completed.
  const { data: session } = await supabase
    .from("sessions")
    .select("id, customer_id, provider_id, status")
    .eq("id", d.sessionId)
    .maybeSingle();
  if (!session || session.customer_id !== profile.id) {
    return { error: "This session isn't available." };
  }

  // One review per session.
  const { data: existing } = await supabase
    .from("reviews")
    .select("id")
    .eq("session_id", d.sessionId)
    .maybeSingle();
  if (existing) return { ok: true };

  const { error: insErr } = await supabase.from("reviews").insert({
    session_id: d.sessionId,
    customer_id: profile.id,
    provider_id: session.provider_id,
    rating: d.rating,
    comment: d.comment ?? null,
    tip_cents: d.tipCents,
  });
  if (insErr) return { error: "We couldn't save your review." };

  // Recompute the provider's rating (privileged column → service role).
  const admin = createAdminClient();
  const { data: ratings } = await admin
    .from("reviews")
    .select("rating")
    .eq("provider_id", session.provider_id);
  const count = ratings?.length ?? 0;
  const sum = (ratings ?? []).reduce((acc, r) => acc + r.rating, 0);
  const avg = count > 0 ? roundHalfUp((sum / count) * 100) / 100 : 0;
  await admin
    .from("providers")
    .update({ rating_avg: avg, rating_count: count })
    .eq("id", session.provider_id);

  revalidatePath(`/session/${session.id}/summary`);
  revalidatePath("/provider/dashboard");
  return { ok: true };
}

"use server";

import { redirect } from "next/navigation";
import { requireRole } from "@/lib/auth";
import { createClient } from "@/lib/supabase/server";
import { getApprovedProvider } from "@/lib/db/queries";
import { getPayments } from "@/lib/integrations/payments";
import { priceForBlock } from "@/lib/pricing";
import { bookingCreateSchema, type BookingCreateInput } from "@/lib/validation/schemas";
import { t } from "@/lib/i18n";

export interface BookingResult {
  error?: string;
  fieldErrors?: Record<string, string>;
}

/**
 * Create a booking and authorise the block-price hold (mock payments). Flow:
 * validate → create booking (pending) → payments.authorizeHold → confirm
 * booking with the payment ref. Capture happens at session end (M6).
 */
export async function createBooking(
  input: BookingCreateInput,
): Promise<BookingResult> {
  const profile = await requireRole("customer");
  if (profile.is_suspended) {
    return { error: t("booking.suspended") };
  }

  const parsed = bookingCreateSchema.safeParse(input);
  if (!parsed.success) {
    const fieldErrors: Record<string, string> = {};
    for (const issue of parsed.error.issues) {
      const key = String(issue.path[0] ?? "");
      if (key && !fieldErrors[key]) fieldErrors[key] = issue.message;
    }
    return { error: "Please check your booking details.", fieldErrors };
  }
  const d = parsed.data;

  const provider = await getApprovedProvider(d.providerId);
  if (!provider) return { error: "This listener isn't available right now." };

  const priceBlockCents = priceForBlock(provider, d.blockMinutes);
  const supabase = await createClient();

  const { data: booking, error: insErr } = await supabase
    .from("bookings")
    .insert({
      customer_id: profile.id,
      provider_id: provider.id,
      slot_id: d.slotId ?? null,
      block_minutes: d.blockMinutes,
      start_mode: d.startMode,
      scheduled_at: d.scheduledAt ?? null,
      price_block_cents: priceBlockCents,
      overage_per_min_cents: provider.overage_per_min_cents,
      status: "pending",
    })
    .select("id")
    .single();

  if (insErr || !booking) {
    return { error: "We couldn't start your booking. Please try again." };
  }

  const payments = getPayments();
  const { customerRef } = await payments.ensureCustomer(profile.id);
  const hold = await payments.authorizeHold({
    bookingId: booking.id,
    amountCents: priceBlockCents,
    customerRef,
  });

  const { error: updErr } = await supabase
    .from("bookings")
    .update({ status: "confirmed", payment_ref: hold.paymentRef })
    .eq("id", booking.id);

  if (updErr) {
    return { error: "We couldn't confirm your booking. Please try again." };
  }

  redirect(`/account?booked=${booking.id}`);
}

