import { test, expect } from "@playwright/test";
import { signIn } from "./utils";

/**
 * Happy path (a): a customer discovers an available listener by voice, books a
 * session, runs the mock call, and rates it.
 * Requires a running local Supabase with the seed (`supabase db reset`).
 */
test("customer can browse, book, run a session, and rate", async ({ page }) => {
  test.setTimeout(90_000);
  await signIn(page, "customer@heard.test", "password123");

  // Narrow to available-now listeners so "Talk now" is offered.
  await page.goto("/browse?available=1");

  // Open the first available listener's profile.
  await page.getByRole("link", { name: /view .* profile/i }).first().click();
  await expect(page).toHaveURL(/\/listeners\//);

  // Talk now → booking.
  await page.getByRole("link", { name: /talk now/i }).click();
  await expect(page).toHaveURL(/\/book\//);

  // 30-min now booking is the default; confirm.
  await page.getByRole("button", { name: /confirm & connect/i }).click();
  await page.waitForURL(/\/account/, { timeout: 20_000 });
  await expect(page.getByText(/you're all set/i)).toBeVisible();

  // Resume the booking from the account page (the banner "Join" link), which
  // opens the session pre-call screen.
  await page.getByRole("link", { name: /^join$/i }).first().click();
  await page.waitForURL(/\/session\//, { timeout: 20_000 });
  await page.getByRole("button", { name: /join the call/i }).click();

  // In-call: the count-up timer runs.
  await expect(page.getByRole("timer")).toBeVisible({ timeout: 20_000 });
  await page.waitForTimeout(2500);

  // End → summary.
  await page.getByRole("button", { name: /end call/i }).click();
  await page.waitForURL(/\/summary/, { timeout: 20_000 });

  // Rate 5 stars and submit.
  await page.getByRole("radio", { name: "5 of 5 stars" }).click();
  await page.getByRole("button", { name: /^submit$/i }).click();
  await expect(page.getByRole("heading", { name: /thank you/i })).toBeVisible();

  // Receipt reflects the captured charge.
  await expect(page.getByText(/receipt/i)).toBeVisible();
});

import { test, expect } from "@playwright/test";
