  await expect(page).toHaveURL(/\/provider\/dashboard/);

  // --- Onboarding ---
  await page.getByRole("link", { name: /finish setting up/i }).first().click();
  await expect(page).toHaveURL(/\/provider\/onboarding/);

  // Step 1: written intro.
  await page
    .getByLabel(/a short written intro/i)
    .fill("Hi, I'm an end-to-end listener who loves a calm chat.");
  await page.getByRole("button", { name: /^next$/i }).click();

