"use server";

import { z } from "zod";
import { revalidatePath } from "next/cache";
import { requireRole } from "@/lib/auth";
import { createAdminClient } from "@/lib/supabase/admin";
import { getPayments } from "@/lib/integrations/payments";
import {
  providerDecisionSchema,
  type ProviderDecision,
} from "@/lib/validation/schemas";
import { type ProviderStatus, type BgCheckStatus } from "@/lib/supabase/types";

const OUTCOME: Record<
  ProviderDecision["decision"],
  { status: ProviderStatus; bg_check_status?: BgCheckStatus }
> = {
  approve: { status: "approved", bg_check_status: "clear" },
  reject: { status: "rejected" },
  suspend: { status: "suspended" },
};

/**
 * Admin decision on a provider: approve (→ clears the background check),
 * reject, or suspend. Role-guarded; writes via the service-role client.
 */
export async function decideProvider(
  input: ProviderDecision,
): Promise<{ ok: boolean; error?: string }> {
  await requireRole("admin");

  const parsed = providerDecisionSchema.safeParse(input);
  if (!parsed.success) return { ok: false, error: "Invalid request." };

  const outcome = OUTCOME[parsed.data.decision];
  const admin = createAdminClient();
  const { error } = await admin
    .from("providers")
    .update(outcome)
    .eq("id", parsed.data.providerId);

  if (error) return { ok: false, error: "Could not update the listener." };
  revalidatePath("/admin/providers");
  return { ok: true };
}

/**
 * Run the weekly payout job (mock): aggregate the period's session earnings +
 * tips into payout rows. Admin-only; returns how many payouts were created.
 */
export async function runWeeklyPayouts(): Promise<{ count: number }> {
  await requireRole("admin");
  const payments = getPayments();
  const { payouts } = await payments.runWeeklyPayouts();
  revalidatePath("/admin/providers");
  revalidatePath("/provider/dashboard");
  return { count: payouts.length };
}

/** Mark a report as reviewed (admin only). */
export async function resolveReport(
  reportId: string,
): Promise<{ ok: boolean }> {
  await requireRole("admin");
  if (!z.string().uuid().safeParse(reportId).success) return { ok: false };
  const admin = createAdminClient();
  const { error } = await admin
    .from("reports")
    .update({ status: "reviewed" })
    .eq("id", reportId);
  if (error) return { ok: false };
  revalidatePath("/admin/reports");
  return { ok: true };
}

const suspendSchema = z.object({
  userId: z.string().uuid(),
  suspended: z.boolean(),
});

/**
 * Suspend or reinstate a user (admin only). Sets profiles.is_suspended; if the
 * user is a provider, also flips their provider status (suspended ⇄ approved)
 * so they leave / re-enter browse. Writes via the service-role client.
 */
export async function setUserSuspended(input: {
  userId: string;
  suspended: boolean;
}): Promise<{ ok: boolean }> {
  await requireRole("admin");
  const parsed = suspendSchema.safeParse(input);
  if (!parsed.success) return { ok: false };
  const { userId, suspended } = parsed.data;

  const admin = createAdminClient();
  const { data: target } = await admin
    .from("profiles")
    .select("role")
    .eq("id", userId)
    .maybeSingle();
  if (!target) return { ok: false };
  // Admins are never suspendable — the UI hides the action; enforce it on the
  // server too so a crafted call can't put an admin into a suspended state.
  if (target.role === "admin") return { ok: false };

  const { error } = await admin
    .from("profiles")
    .update({ is_suspended: suspended })
    .eq("id", userId);
  if (error) return { ok: false };

  if (target.role === "provider") {
    // Only toggle the browse/approval gate for providers that are actually in
    // the approved⇄suspended pair. Never overwrite a pending/rejected status on
    // suspend (it would be lost), and never auto-approve a pending/rejected
    // provider on reinstate (that would bypass the M3/M4 vetting gate).
    const { data: prov } = await admin
      .from("providers")
      .select("status")
      .eq("id", userId)
      .maybeSingle();
    if (suspended && prov?.status === "approved") {
      await admin.from("providers").update({ status: "suspended" }).eq("id", userId);
    } else if (!suspended && prov?.status === "suspended") {
      await admin.from("providers").update({ status: "approved" }).eq("id", userId);
    }
  }

  revalidatePath("/admin/users");
  revalidatePath("/admin/reports");
  return { ok: true };
}

