import { z } from "zod";
import { revalidatePath } from "next/cache";
import { requireRole } from "@/lib/auth";
import { createClient } from "@/lib/supabase/server";
import { getPayments } from "@/lib/integrations/payments";
import { cancellationOutcome } from "@/lib/pricing";

const uuid = z.string().uuid();

/** Save a listener to the customer's favorites (idempotent). */
export async function addFavorite(
  providerId: string,
): Promise<{ ok: boolean }> {
  const profile = await requireRole("customer");
  if (!uuid.safeParse(providerId).success) return { ok: false };
  const supabase = await createClient();
  const { error } = await supabase
    .from("favorites")
    .upsert(
      { customer_id: profile.id, provider_id: providerId },
      { onConflict: "customer_id,provider_id", ignoreDuplicates: true },
    );
  if (error) return { ok: false };
  revalidatePath("/account");
  return { ok: true };
}

/** Remove a listener from the customer's favorites. */
export async function removeFavorite(
  providerId: string,
): Promise<{ ok: boolean }> {
  const profile = await requireRole("customer");
  const supabase = await createClient();
  const { error } = await supabase
    .from("favorites")
    .delete()
    .eq("customer_id", profile.id)
    .eq("provider_id", providerId);
  if (error) return { ok: false };
  revalidatePath("/account");
  return { ok: true };
}

export interface CancelResult {
  ok: boolean;
  released?: boolean;
  error?: string;
}

/**
 * Cancel a confirmed booking. Cancellation policy (SPEC §5): a scheduled session
 * cancelled ≥1h before its start releases the hold, otherwise the block is
 * charged. A "now" booking that was never joined releases (the customer never
 * talked — "you're in control, leave any time"). Capture/refund go through the
 * payments adapter.
 */
export async function cancelBooking(bookingId: string): Promise<CancelResult> {
  const profile = await requireRole("customer");
  if (!uuid.safeParse(bookingId).success) {
    return { ok: false, error: "Booking not found." };
  }
  const supabase = await createClient();

  const { data: booking } = await supabase
    .from("bookings")
    .select("*")
    .eq("id", bookingId)
    .maybeSingle();
  if (!booking || booking.customer_id !== profile.id) {
    return { ok: false, error: "Booking not found." };
  }
  if (booking.status !== "confirmed") {
    return { ok: false, error: "This booking can't be cancelled." };
  }

  let release: boolean;
  if (booking.start_mode === "scheduled") {
    release =
      cancellationOutcome({
        priceBlockCents: booking.price_block_cents,
        scheduledAt: booking.scheduled_at,
        nowMs: Date.now(),
      }).action === "release";
  } else {
    release = true; // a "now" booking that was never joined
  }

  // Make the status transition the gate for the money side-effect: only the
  // call that actually flips confirmed → cancelled proceeds to refund/capture,
  // so a concurrent/retried cancel can't double-refund or double-capture.
  const { data: transitioned, error } = await supabase
    .from("bookings")
    .update({ status: "cancelled" })
    .eq("id", bookingId)
    .eq("customer_id", profile.id)
    .eq("status", "confirmed")
    .select("id");
  if (error) return { ok: false, error: "Could not cancel the booking." };
  if (!transitioned || transitioned.length === 0) {
    return { ok: false, error: "This booking can't be cancelled." };
  }

  const payments = getPayments();
  if (booking.payment_ref) {
    if (release) {
      await payments.refund({
        paymentRef: booking.payment_ref,
        amountCents: booking.price_block_cents,
      });
    } else {
      await payments.capture({
        paymentRef: booking.payment_ref,
        amountCents: booking.price_block_cents,
      });
    }
  }

  revalidatePath("/account");
  return { ok: true, released: release };
}

const rescheduleSchema = z.object({
  bookingId: uuid,
  scheduledAt: z.string().datetime(),
});

/** Move a confirmed booking to a new future time. */
export async function rescheduleBooking(input: {
  bookingId: string;
  scheduledAt: string;
}): Promise<{ ok: boolean; error?: string }> {
  const profile = await requireRole("customer");
  const parsed = rescheduleSchema.safeParse(input);
  if (!parsed.success) return { ok: false, error: "Pick a valid time." };
  if (new Date(parsed.data.scheduledAt).getTime() <= Date.now()) {
    return { ok: false, error: "Pick a time in the future." };
  }

  const supabase = await createClient();
  const { error } = await supabase
    .from("bookings")
    .update({
      scheduled_at: parsed.data.scheduledAt,
      start_mode: "scheduled",
    })
    .eq("id", parsed.data.bookingId)
    .eq("customer_id", profile.id)
    .eq("status", "confirmed");
  if (error) return { ok: false, error: "Could not reschedule." };

  revalidatePath("/account");
  return { ok: true };
}

/** Update the customer's display name. */
export async function updateProfileName(
  name: string,
): Promise<{ ok: boolean; error?: string }> {
  const profile = await requireRole("customer");
  const trimmed = name.trim();
  if (trimmed.length < 1 || trimmed.length > 120) {
    return { ok: false, error: "Enter your name." };
  }
  const supabase = await createClient();
  const { error } = await supabase
    .from("profiles")
    .update({ full_name: trimmed })
    .eq("id", profile.id);
  if (error) return { ok: false, error: "Could not save your name." };
  revalidatePath("/account/settings");
  return { ok: true };
}

"use server";

import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { homeForRole } from "@/lib/auth";
import { signInSchema, signUpSchema } from "@/lib/validation/schemas";
import { t } from "@/lib/i18n";
import { type UserRole } from "@/lib/supabase/types";

export interface AuthFormState {
  error?: string;
  fieldErrors?: Record<string, string>;
}

function fieldErrorsFrom(
  issues: { path: (string | number)[]; message: string }[],
): Record<string, string> {
  const out: Record<string, string> = {};
  for (const issue of issues) {
    const key = String(issue.path[0] ?? "");
    if (key && !out[key]) out[key] = issue.message;
  }
  return out;
}

export async function signUpAction(
  _prev: AuthFormState,
  formData: FormData,
): Promise<AuthFormState> {
  const parsed = signUpSchema.safeParse({
    fullName: formData.get("fullName"),
    email: formData.get("email"),
    password: formData.get("password"),
    role: formData.get("role"),
  });

  if (!parsed.success) {
    return { fieldErrors: fieldErrorsFrom(parsed.error.issues) };
  }

  const { fullName, email, password, role } = parsed.data;
  const supabase = await createClient();

  const { error } = await supabase.auth.signUp({
    email,
    password,
    options: {
      data: { role, full_name: fullName },
    },
  });

  if (error) {
    if (
      error.message.toLowerCase().includes("already") ||
      error.code === "user_already_exists"
    ) {
      return { error: t("auth.errorEmailTaken") };
    }
    return { error: t("auth.errorGeneric") };
  }

  // Email confirmation is disabled locally, so a session now exists.
  redirect(homeForRole(role));
}

export async function signInAction(
  _prev: AuthFormState,
  formData: FormData,
): Promise<AuthFormState> {
  const parsed = signInSchema.safeParse({
    email: formData.get("email"),
    password: formData.get("password"),
  });

  if (!parsed.success) {
    return { fieldErrors: fieldErrorsFrom(parsed.error.issues) };
  }

  const supabase = await createClient();
  const { error } = await supabase.auth.signInWithPassword(parsed.data);

  if (error) {
    return { error: t("auth.errorInvalid") };
  }

  const {
    data: { user },
  } = await supabase.auth.getUser();
  let role: UserRole = "customer";
  if (user) {
    const { data } = await supabase
      .from("profiles")
      .select("*")
      .eq("id", user.id)
      .maybeSingle();
    if (data?.role) role = data.role;
  }

  const nextParam = formData.get("next");
  redirect(typeof nextParam === "string" && nextParam.startsWith("/")
    ? nextParam
    : homeForRole(role));
}

export async function signOutAction(): Promise<void> {
  const supabase = await createClient();
  await supabase.auth.signOut();
  redirect("/signin");
}

"use server";

import { z } from "zod";
import { redirect } from "next/navigation";
import { revalidatePath } from "next/cache";
import { requireRole } from "@/lib/auth";
import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { providerOnboardingSchema } from "@/lib/validation/schemas";
import { getBackgroundCheck } from "@/lib/integrations/background-check";

const onboardingPayloadSchema = providerOnboardingSchema.extend({
  isAvailableNow: z.boolean().default(false),
});

export type OnboardingInput = z.input<typeof onboardingPayloadSchema>;

export interface OnboardingResult {
  ok?: true;
  error?: string;
  fieldErrors?: Record<string, string>;
}

/**
 * Complete provider onboarding: validate, save the profile + economics, kick
 * off the (mock) background check, and leave the provider in `pending` for
 * admin approval (M4). Writes via the service-role client scoped to the caller's
 * own id, so privileged columns (status/rating) are set deliberately here and
 * the provider can't change them directly (see providers_guard_privileged).
 */
export async function completeOnboarding(
  input: OnboardingInput,
): Promise<OnboardingResult> {
  const profile = await requireRole("provider");

  const parsed = onboardingPayloadSchema.safeParse(input);
  if (!parsed.success) {
    const fieldErrors: Record<string, string> = {};
    for (const issue of parsed.error.issues) {
      const key = String(issue.path[0] ?? "");
      if (key && !fieldErrors[key]) fieldErrors[key] = issue.message;
    }
    return { error: "Please check the highlighted fields.", fieldErrors };
  }

  const d = parsed.data;
  const bgCheck = getBackgroundCheck();
  const { checkRef, status: bgStatus } = await bgCheck.initiate({
    providerId: profile.id,
  });

  const admin = createAdminClient();
  const { error } = await admin
    .from("providers")
    .update({
      display_name: d.displayName,
      bio: d.bio,
      voice_intro_path: d.voiceIntroPath ?? null,
      languages: d.languages,
      topics: d.topics,
      price_block_15_cents: d.priceBlock15Cents,
      price_block_30_cents: d.priceBlock30Cents,
      price_block_45_cents: d.priceBlock45Cents,
      overage_per_min_cents: d.overagePerMinCents,
      is_available_now: d.isAvailableNow,
      bg_check_ref: checkRef,
      bg_check_status: bgStatus,
      status: "pending",
    })
    .eq("id", profile.id);

  if (error) {
    return { error: "We couldn't save your profile. Please try again." };
  }

  revalidatePath("/provider/dashboard");
  redirect("/provider/dashboard?onboarded=1");
}

/** Decline (cancel) an incoming booking made with the signed-in provider. */
export async function declineBooking(
  bookingId: string,
): Promise<{ ok: boolean }> {
  const profile = await requireRole("provider");
  const supabase = await createClient();
  const { error } = await supabase
    .from("bookings")
    .update({ status: "cancelled" })
    .eq("id", bookingId)
    .eq("provider_id", profile.id);
  if (error) return { ok: false };
  revalidatePath("/provider/dashboard");
  return { ok: true };
}

/** Toggle the provider's "Available now" state (own row, RLS-enforced). */
export async function setAvailability(
  isAvailableNow: boolean,
): Promise<{ ok: boolean }> {
  const profile = await requireRole("provider");
  const supabase = await createClient();
  const { error } = await supabase
    .from("providers")
    .update({ is_available_now: isAvailableNow })
    .eq("id", profile.id);
  if (error) return { ok: false };
  revalidatePath("/provider/dashboard");
  return { ok: true };
}

