"use server";

import { getUser } from "@/lib/auth";
import { createClient } from "@/lib/supabase/server";
import { reportSchema, type ReportInput } from "@/lib/validation/schemas";

export interface ReportResult {
  ok?: true;
  error?: string;
}

/**
 * Minimal "Report a problem" safety hook: writes a row to `reports`
 * (reporter-owned via RLS). The moderation/review UI is deferred (SPEC §12);
 * this just captures the report so nothing is lost.
 */
export async function submitReport(input: ReportInput): Promise<ReportResult> {
  const user = await getUser();
  if (!user) return { error: "Please sign in to report a problem." };

  const parsed = reportSchema.safeParse(input);
  if (!parsed.success) return { error: "Please tell us what happened." };

  const supabase = await createClient();
  const { error } = await supabase.from("reports").insert({
    reporter_id: user.id,
    target_id: parsed.data.targetId ?? null,
    session_id: parsed.data.sessionId ?? null,
    reason: parsed.data.reason,
  });
  if (error) return { error: "We couldn't send your report. Please try again." };

  return { ok: true };
}

