import { readFileSync } from "node:fs";
import { join } from "node:path";
import { type Page, expect } from "@playwright/test";

/** Read a key from the app's .env.local (the test process doesn't load it). */
function envLocal(key: string): string {
  const file = readFileSync(join(process.cwd(), ".env.local"), "utf8");
  const line = file.split("\n").find((l) => l.startsWith(`${key}=`));
  return line ? line.slice(key.length + 1).trim() : "";
}

/**
 * Reset the seeded safety report (Walter → Casey) back to `open` via the
 * service-role REST API, so the "admin actions a report" E2E is re-runnable
 * without a full `supabase db reset` between runs.
 */
export async function resetSeedReportToOpen() {
  const url = envLocal("NEXT_PUBLIC_SUPABASE_URL");
  const key = envLocal("SUPABASE_SERVICE_ROLE_KEY");
  if (!url || !key) return; // best-effort; CI seeds fresh anyway
  const WALTER = "00000000-0000-0000-0000-000000000004";
  const CASEY = "00000000-0000-0000-0000-0000000000c1";
  await fetch(
    `${url}/rest/v1/reports?reporter_id=eq.${WALTER}&target_id=eq.${CASEY}`,
    {
      method: "PATCH",
      headers: {
        apikey: key,
        Authorization: `Bearer ${key}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ status: "open" }),
    },
  );
}

/** Sign in through the real form and wait to land somewhere authenticated. */
export async function signIn(page: Page, email: string, password: string) {
  await page.goto("/signin");
  await page.getByLabel(/email address/i).fill(email);
  await page.getByLabel(/^password/i).fill(password);
  await page.getByRole("button", { name: /^sign in$/i }).click();
  await expect(page).not.toHaveURL(/\/signin/);
}

/** Sign out via the header control. */
export async function signOut(page: Page) {
  await page.getByRole("button", { name: /sign out/i }).click();
  await page.waitForURL(/\/signin/);
}

