/**
 * Status enum → { tone, localized label, paired icon }. Meaning is carried by
 * icon + human text together (never a raw DB token or colour alone), matching
 * the other status pills across the app.
 */
type StatusMeta = { tone: StatusTone; labelKey: MessageKey; icon: LucideIcon };

const SESSION_STATUS: Record<string, StatusMeta> = {
  completed: { tone: "success", labelKey: "admin.sessCompleted", icon: CircleCheck },
  in_progress: { tone: "info", labelKey: "admin.sessInProgress", icon: PhoneCall },
  cancelled: { tone: "neutral", labelKey: "admin.sessCancelled", icon: XCircle },
};
const PAYMENT_STATUS: Record<string, StatusMeta> = {
  authorized: { tone: "neutral", labelKey: "admin.payAuthorized", icon: Clock },
  captured: { tone: "success", labelKey: "admin.payCaptured", icon: CircleCheck },
  refunded: { tone: "neutral", labelKey: "admin.payRefunded", icon: RotateCcw },
  failed: { tone: "alert", labelKey: "admin.payFailed", icon: XCircle },
};
const PAYOUT_STATUS: Record<string, StatusMeta> = {
  paid: { tone: "success", labelKey: "admin.payoutPaid", icon: CircleCheck },
  scheduled: { tone: "warning", labelKey: "admin.payoutScheduled", icon: Clock },
};

function StatusCell({
  status,
  meta,
}: {
  status: string;
  meta: Record<string, StatusMeta>;
}) {
  const m = meta[status];
  if (!m) return <StatusBadge tone="neutral">{status}</StatusBadge>;
  return (
    <StatusBadge tone={m.tone} icon={m.icon}>
      {t(m.labelKey)}
    </StatusBadge>
  );
}

